sqlite3 -readonly /app/oewn.sqlite "
SELECT 'words_total', COUNT(*), COUNT(DISTINCT wordid), MIN(wordid), MAX(wordid) FROM words;
SELECT 'synsets_total', COUNT(*), COUNT(DISTINCT synsetid), MIN(synsetid), MAX(synsetid) FROM synsets;
SELECT 'senses_total', COUNT(*), COUNT(DISTINCT senseid), COUNT(DISTINCT wordid), COUNT(DISTINCT synsetid) FROM senses;
SELECT 'domains_distinct_in_synsets', COUNT(DISTINCT domainid), MIN(domainid), MAX(domainid) FROM synsets;
SELECT 'posids_distinct_in_synsets', COUNT(DISTINCT posid) FROM synsets;
"

sqlite3 -readonly /app/oewn.sqlite "
SELECT 'words_rowid_mismatch', COUNT(*) FROM words WHERE rowid != wordid;
SELECT 'synsets_rowid_mismatch', COUNT(*) FROM synsets WHERE rowid != synsetid;
SELECT 'senses_orphan_word', COUNT(*) FROM senses s LEFT JOIN words w ON s.wordid = w.wordid WHERE w.wordid IS NULL;
SELECT 'senses_orphan_synset', COUNT(*) FROM senses s LEFT JOIN synsets syn ON s.synsetid = syn.synsetid WHERE syn.synsetid IS NULL;
SELECT 'senses_dup_word_synset', COUNT(*) FROM (SELECT wordid, synsetid, COUNT(*) c FROM senses GROUP BY wordid, synsetid HAVING c > 1);
SELECT * FROM senses LIMIT 5;
SELECT * FROM words LIMIT 5;
SELECT * FROM synsets LIMIT 5;
"

